package com.tietsync.academic;
import org.springframework.stereotype.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.security.crypto.password.PasswordEncoder; import java.util.*; import java.time.*;
@Service class AcademicService { final UserRepository users; final AssignmentRepository assignments; final AttendanceRepository attendance; final SlotRepository slots; final ConsultationRepository consultations; final PasswordEncoder encoder;
 AcademicService(UserRepository u,AssignmentRepository a,AttendanceRepository at,SlotRepository s,ConsultationRepository c,PasswordEncoder e){users=u;assignments=a;attendance=at;slots=s;consultations=c;encoder=e;}
 UserAccount user(UUID id){return users.findById(id).orElseThrow(()->new IllegalArgumentException("User not found"));}
 @Transactional ConsultationRequest book(UUID studentId,UUID slotId,String description){UserAccount student=user(studentId);if(student.role!=Role.STUDENT)throw new IllegalArgumentException("Only students can create consultation requests"); ConsultationSlot slot=slots.findById(slotId).orElseThrow(()->new IllegalArgumentException("Slot not found"));if(!slot.available)throw new IllegalArgumentException("This consultation slot is no longer available");slot.available=false; ConsultationRequest r=new ConsultationRequest();r.student=student;r.faculty=slot.faculty;r.slot=slot;r.description=description;r.status=RequestStatus.PENDING;return consultations.save(r);}
 @Transactional ConsultationRequest decide(UUID facultyId,UUID requestId,RequestStatus status){UserAccount faculty=user(facultyId);if(faculty.role!=Role.FACULTY)throw new IllegalArgumentException("Only faculty can decide consultation requests");if(status!=RequestStatus.APPROVED&&status!=RequestStatus.REJECTED)throw new IllegalArgumentException("Faculty may only approve or reject pending requests");ConsultationRequest r=consultations.findById(requestId).orElseThrow(()->new IllegalArgumentException("Request not found"));if(!r.faculty.id.equals(facultyId))throw new IllegalArgumentException("You cannot manage this request");if(r.status!=RequestStatus.PENDING)throw new IllegalArgumentException("Only pending requests can be updated");r.status=status;if(status==RequestStatus.REJECTED)r.slot.available=true;return r;}
 @Transactional ConsultationRequest cancel(UUID studentId,UUID requestId){UserAccount student=user(studentId);if(student.role!=Role.STUDENT)throw new IllegalArgumentException("Only students can cancel consultation requests");ConsultationRequest r=consultations.findById(requestId).orElseThrow(()->new IllegalArgumentException("Request not found"));if(!r.student.id.equals(studentId))throw new IllegalArgumentException("You cannot cancel this request");if(r.status!=RequestStatus.PENDING)throw new IllegalArgumentException("Only pending requests can be cancelled");r.status=RequestStatus.CANCELLED;r.slot.available=true;return r;}
 int additionalClasses(int attended,int total){ if(total<=0||attended*4>=total*3)return 0;return (int)Math.ceil((.75*total-attended)/.25); }
}
